function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: string }) {
  const tones: Record<string, string> = {
    teal: "bg-primary/10 text-primary border-primary/20", amber: "bg-accent/15 text-foreground border-accent/30",
    red: "bg-destructive/10 text-destructive border-destructive/20", blue: "bg-chart-3/10 text-chart-3 border-chart-3/20",
    neutral: "bg-muted text-muted-foreground border-border", green: "bg-emerald-500/10 text-emerald-700 border-emerald-500/20"
  };
  return <span className={`inline-flex items-center rounded-full border px-2.5 py-1 text-[11px] font-semibold ${tones[tone] ?? tones.neutral}`}>{children}</span>;
}
function statusTone(status = "") { const s = status.toLowerCase(); return s.includes("approve") || s.includes("preferred") || s.includes("delivered") || s.includes("on track") ? "green" : s.includes("risk") || s.includes("urgent") || s.includes("reject") || s.includes("delay") ? "red" : s.includes("pending") || s.includes("sourcing") || s.includes("transit") ? "amber" : "blue"; }

function Skeleton({ className = "" }: { className?: string }) { return <div className={`aqura-skeleton rounded-lg ${className}`} aria-label="Loading" />; }
