function BarChart({ values }: { values: { month: string; amount: number }[] }) { const max = Math.max(...values.map((v) => v.amount), 1); return <div className="flex h-48 items-end gap-2 px-5 pb-2 pt-6 sm:gap-4">{values.map((item, i) => <div key={item.month} className="group flex h-full flex-1 flex-col justify-end gap-2"><div className="relative min-h-[4px] rounded-t-md bg-primary/80 transition-all group-hover:bg-primary" style={{ height: `${Math.max(7, item.amount / max * 100)}%` }}><span className="pointer-events-none absolute -top-7 left-1/2 -translate-x-1/2 rounded bg-sidebar px-1.5 py-1 text-[10px] text-white opacity-0 transition-opacity group-hover:opacity-100">{money(item.amount)}</span></div><span className="text-center font-mono text-[10px] text-muted-foreground">{item.month}</span></div>)}</div>; }

